import type { StyleProp } from "./style-types";
import type { IconName } from "@rezumi/schema/icons";
import type { IconStyle } from "@rezumi/schema/resume/data";
import { upgradeIconName } from "@rezumi/schema/resume/icon-names";
import { commonIcons, expandIcon, iconFiles } from "./hugeicons";
import { Svg } from "./primitives";
import { flattenStyle, parseColor } from "./style";

export type { IconName };

type IconFile = `${IconStyle}/${"common" | "rest"}`;

// Icon drawings (generated by `pnpm --filter @rezumi/tooling icons:pdf`) load as renders first ask for them, per
// style: the ~30 most resumes draw (5–9 KB gzipped), then all the rest (175–275 KB) only when a render draws another.
const icons = new Map<string, string>();
const loaded = new Set<IconFile>();
const loading = new Map<IconFile, Promise<void>>();
const requested = new Set<IconFile>();

const loadFile = (file: IconFile) => {
	let promise = loading.get(file);
	if (!promise) {
		const [style, part] = file.split("/") as [IconStyle, "common" | "rest"];
		promise = iconFiles[style][part]().then(
			(module) => {
				for (const [name, markup] of Object.entries(module.default)) icons.set(`${style}/${name}`, expandIcon(markup));
				loaded.add(file);
			},
			(error: unknown) => {
				// A failed download may succeed next time.
				loading.delete(file);
				throw error;
			},
		);
		loading.set(file, promise);
	}
	return promise;
};

/** Loads every icon of every style, for tests. */
export const loadAllIcons = () =>
	Promise.all(
		(Object.keys(iconFiles) as IconStyle[]).flatMap((style) => [
			loadFile(`${style}/common`),
			loadFile(`${style}/rest`),
		]),
	);

/**
 * Loads the icon files the renders since the last call asked for and didn't have. Returns whether any loaded, so
 * the caller knows to render again.
 */
export async function loadRequestedIcons(): Promise<boolean> {
	const files = [...requested];
	requested.clear();
	await Promise.all(files.map(loadFile));
	return files.length > 0;
}

type ResumeIconProps = {
	/** A resume icon name; a former Phosphor name draws its closest match. */
	name: IconName | string;
	size?: number | string | undefined;
	color?: string | undefined;
	opacity?: number | string | undefined;
	/** "none" hides the icon, as on react-pdf's SVG. */
	display?: "none" | "flex" | undefined;
	/** The resume's icon style. */
	variant?: IconStyle | undefined;
	style?: StyleProp | undefined;
};

/** A Hugeicons stroke icon in the resume's icon style, drawn as vector paths. An unknown name draws nothing. */
export function ResumeIcon({
	name,
	size = 16,
	color = "currentColor",
	opacity,
	display,
	variant = "standard",
	style,
}: ResumeIconProps) {
	const icon = upgradeIconName(name);
	if (display === "none" || !icon || icon === "none") return null;
	const markup = icons.get(`${variant}/${icon}`);
	if (!markup) {
		const file: IconFile = `${variant}/${commonIcons.has(icon) ? "common" : "rest"}`;
		if (!loaded.has(file)) requested.add(file);
		return null;
	}
	// "currentColor" means the colour the template set on the icon's style, as in react-pdf.
	const { opacity: styleOpacity, ...flat } = flattenStyle(style);
	// Forme 0.25 let an SVG's opacity leak into whatever it drew next, so it goes into the paint instead.
	const alpha = Number(opacity ?? styleOpacity ?? 1);
	return (
		<Svg
			viewBox="0 0 24 24"
			width={size}
			height={size}
			content={paint(markup, color === "currentColor" ? (flat.color ?? "#000000") : color, alpha)}
			style={flat}
		/>
	);
}

/** The icon's markup in a CSS colour: hex paint, with rgba's alpha times `opacity` on every shape. */
function paint(markup: string, color: string, opacity: number) {
	const { rgb, alpha: colorAlpha } = parseColor(color) ?? { rgb: [0, 0, 0], alpha: 1 };
	const hex = `#${rgb.map((channel) => Math.round(channel).toString(16).padStart(2, "0")).join("")}`;
	const alpha = Math.max(0, Math.min(1, colorAlpha * (Number.isFinite(opacity) ? opacity : 1)));
	const painted = markup.replaceAll("currentColor", hex);
	return alpha < 1
		? painted.replace(/<(path|circle|rect|ellipse) /g, `<$1 fill-opacity="${alpha}" stroke-opacity="${alpha}" `)
		: painted;
}
